<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import http from '../../api/http'
import { getAccessToken } from '../../api/auth'
const route=useRoute();const router=useRouter();const token=ref('');const questions=ref([]);const answers=ref({});const config=ref({});const result=ref(null);const expiry=ref(0);const now=ref(Date.now());const loading=ref(true);const error=ref('');const saving=ref(false);const saved=ref(false);let interval
async function choose(questionId,key){if(answers.value[questionId]||seconds.value===0)return;answers.value={...answers.value,[questionId]:key};try{await http.put(`/gk/exams/${encodeURIComponent(token.value)}/answers`,{answers:answers.value})}catch(e){error.value=e.response?.data?.message||'উত্তর সংরক্ষণ হয়নি।'}}const seconds=computed(()=>Math.max(0,Math.ceil((expiry.value-now.value)/1000)));const displayedScore=computed(()=>{const score=Number(result.value?.score);return Number.isFinite(score)?score:0});const clock=computed(()=>`${String(Math.floor(seconds.value/60)).padStart(2,'0')}:${String(seconds.value%60).padStart(2,'0')}`)
function number(i){return config.value.numbering_style==='bangla'?String(i+1).replace(/[0-9]/g,n=>'০১২৩৪৫৬৭৮৯'[n]):i+1}
async function submit(auto=false){if(result.value||!token.value)return;try{const {data}=await http.post(`/gk/exams/${encodeURIComponent(token.value)}/submit`,auto?{answers:{}}:{answers:answers.value});result.value=data.result;saved.value=data.saved}catch(e){error.value=e.response?.data?.message||'ফলাফল জমা হয়নি।'}}
async function save(){if(!getAccessToken()){await router.push({name:'account',query:{redirect:route.fullPath+'?save=1'}});return}saving.value=true;try{await http.post(`/gk/exams/${encodeURIComponent(token.value)}/save`);saved.value=true}catch(e){error.value=e.response?.data?.message||'ফলাফল সংরক্ষণ হয়নি।'}finally{saving.value=false}}
onMounted(async()=>{try{const {data}=await http.post(`/gk/exam-papers/${route.params.paperId}/start`);token.value=data.exam_token;questions.value=data.questions;config.value=data.exam_config;expiry.value=new Date(data.expires_at).getTime()}catch(e){error.value=e.response?.data?.message||'পরীক্ষা শুরু করা যায়নি।'}finally{loading.value=false}interval=setInterval(()=>{now.value=Date.now();if(!loading.value&&!result.value&&seconds.value===0)submit(true)},500)})
onBeforeUnmount(()=>clearInterval(interval))
</script>
<template><main class="container-page py-8"><div class="mx-auto max-w-5xl"><header class="mb-5 grid grid-cols-3 items-center rounded-2xl border bg-white p-4"><RouterLink to="/" class="font-extrabold text-emerald-800">সহজপাঠ</RouterLink><h1 class="text-center font-black md:text-xl">{{ config.title||'MCQ পরীক্ষা' }}</h1><b class="text-right font-mono text-rose-700">{{ clock }}</b></header><p v-if="loading" class="surface p-10 text-center">পরীক্ষা প্রস্তুত হচ্ছে…</p><p v-else-if="error&&!questions.length" class="surface p-8 text-center text-rose-700">{{ error }} <RouterLink to="/gk/exam-categories" class="font-bold">বিভাগে ফিরুন</RouterLink></p><template v-else-if="result"><section class="surface mb-5 p-7 text-center"><p class="text-sm font-bold text-emerald-700">পরীক্ষার ফলাফল</p><p class="my-2 text-5xl font-black">{{ displayedScore }}</p><p>মোট {{ result.total_marks }} নম্বর · সঠিক {{ result.correct_count }} · ভুল {{ result.wrong_count }} · কাটা {{ result.wrong_cut_marks }}</p></section><section class="grid gap-3"><article v-for="item in result.wrong_answers" :key="item.number" class="surface p-5"><b>{{ item.number }}. {{ item.question }}</b><p class="mt-2 text-rose-700">আপনার উত্তর: {{ item.selected_answer }}</p><p class="font-bold text-emerald-700">সঠিক উত্তর: {{ item.correct_answer }}</p></article></section><div class="mt-5 flex justify-center gap-3"><button v-if="!saved" class="btn-primary" :disabled="saving" @click="save">{{ saving?'সংরক্ষণ হচ্ছে…':'Save this record' }}</button><RouterLink v-else to="/profile" class="btn-primary">Profile দেখুন</RouterLink><RouterLink to="/gk/exam-categories" class="rounded-xl border px-4 py-3">বিভাগে ফিরুন</RouterLink></div><p v-if="error" class="mt-4 text-center text-rose-700">{{ error }}</p></template><template v-else><div class="mx-auto max-w-5xl"><div v-if="config.notice_text" class="notice-marquee mb-4 overflow-hidden rounded-xl border border-rose-200 bg-rose-50 py-2 text-sm font-bold text-rose-800"><div class="notice-marquee__track w-max whitespace-nowrap px-4">{{ config.notice_text }}</div></div><section class="panel relative mx-auto w-full max-w-5xl overflow-hidden rounded-2xl border border-slate-200 bg-white p-7 shadow-sm md:p-12"><span v-if="config.watermark" class="pointer-events-none absolute inset-0 flex select-none items-center justify-center overflow-hidden text-6xl font-black text-slate-200/40" style="transform:rotate(-30deg)">{{ config.watermark }}</span><header class="relative mb-7 border-b pb-4 text-center"><p v-if="config.category_name" class="text-sm text-slate-600">{{ config.category_name }}</p><h1 class="mt-1 text-xl font-black text-slate-900 md:text-2xl">{{ config.title || 'MCQ Exam' }}</h1><p class="mt-1 text-sm text-slate-700">Duration: {{ config.duration_minutes }} minutes | Questions: {{ questions.length }}</p></header><div class="relative grid gap-5" :class="[2,5].includes(Number(config.layout_template)) ? 'md:grid-cols-2' : 'grid-cols-1'"><article v-for="(q,i) in questions" :key="q.id" class="break-inside-avoid text-sm"><p class="font-bold leading-6 text-slate-900">{{ number(i) }}. {{ q.question }}</p><div class="mt-2 grid grid-cols-2 gap-1"><label v-for="key in ['a','b','c','d']" :key="key" class="flex items-start gap-1.5 rounded px-1 py-0.5 text-sm leading-6 transition-colors" :class="[answers[q.id]===key ? 'bg-emerald-50 font-semibold text-emerald-800' : 'text-slate-800', answers[q.id]||seconds===0 ? 'cursor-default' : 'cursor-pointer hover:bg-slate-50']"><input class="sr-only" type="radio" :name="'q'+q.id" :value="key" :checked="answers[q.id]===key" :disabled="!!answers[q.id]||seconds===0" @change="choose(q.id,key)"><span v-if="config.option_style==='alphabet'" class="shrink-0">{{ key.toUpperCase() }})</span><span v-else aria-hidden="true" class="shrink-0">&#9675;</span><span>{{ q['option_'+key] }}</span></label></div></article></div></section><div class="mt-5 text-center"><button class="btn-primary" :disabled="seconds===0" @click="submit()">Submit exam</button><p class="mt-2 text-xs text-slate-500">Answers cannot be changed after selection.</p><p v-if="error" class="mt-3 text-sm text-rose-700">{{ error }}</p></div></div></template></div></main></template>
<style scoped>
.notice-marquee__track { animation: exam-notice-marquee 18s linear infinite; }
.notice-marquee:hover .notice-marquee__track { animation-play-state: paused; }
@keyframes exam-notice-marquee { from { transform: translateX(100%); } to { transform: translateX(-100%); } }
@media (prefers-reduced-motion: reduce) { .notice-marquee__track { animation: none; transform: none; } }
</style>
